X(0) Y(1)    
</code></pre>

Q: CTAD in a variadic template function A: <p>Just a different solution than Jarod42's one (not better, just another way to answer the problem):</p>
<pre class="lang-cpp prettyprint-override"><code>#include &lt;iostream&gt;
#include &lt;source_location&gt;
#include &lt;type_traits&gt;
#include &lt;vector&gt;

enum class bar {
    bar1,
    bar2,
};

namespace detail {
// first type argument will change during recursive call thus need to be
// explicitly passed
template &lt;typename First, typename... Ts&gt;
void debug_disp(
    First f, Ts&amp;&amp;... ts,
    const std::source_location&amp; loc = std::source_location::current()) {
    std::cout &lt;&lt; loc.function_name() &lt;&lt; &quot; line &quot; &lt;&lt; loc.line() &lt;&lt; &quot;: &quot;;
    std::cout &lt;&lt; static_cast&lt;std::underlying_type_t&lt;bar&gt;&gt;(f[0]) &lt;&lt; &quot; &quot;
              &lt;&lt; static_cast&lt;std::underlying_type_t&lt;bar&gt;&gt;(f[1]) &lt;&lt; &quot; &quot;;
    ((std::cout &lt;&lt; std::forward&lt;Ts&gt;(ts) &lt;&lt; &quot; &quot;), ...);
    std::cout &lt;&lt; '\n';
}
}  // namespace detail

template &lt;typename First, typename... Ts&gt;
struct debug {
    // dispatching to the right display function
    debug(First f, Ts&amp;&amp;... ts,
          const std::source_location&amp; loc = std::source_location::current()) {
        if constexpr (std::is_same_v&lt;bar, First&gt;) {
            // first arg is enum, call with a vector of twice the enumerator
            detail::debug_disp&lt;std::vector&lt;First&gt;, Ts...&gt;(
                std::vector{f, f}, std::forward&lt;Ts&gt;(ts)..., loc);
        } else {
            if constexpr (std::is_same_v&lt;std::vector&lt;bar&gt;, First&gt;) {
                // first arg is a vector of bar: displays
                detail::debug_disp&lt;First, Ts...&gt;(f, std::forward&lt;Ts&gt;(ts)...,
                                                 loc);
            } else {
                // default first argument {bar::bar1, bar::bar1} is now added
                detail::debug_disp&lt;std::vector&lt;bar&gt;, First, Ts...&gt;(
                    {bar::bar1, bar::bar1}, std::forward&lt;First&gt;(f),
                    std::forward&lt;Ts&gt;(ts)..., loc);
            }
        }
    }
};

template &lt;typename First, typename... Ts&gt;
debug(First&amp;&amp;, Ts&amp;&amp;...) -&gt; debug&lt;First, Ts...&gt;;
// required to properly get this kind of syntax: debug({bar::bar1, bar::bar2},
// 5, 'A', 3.14f, &quot;foo&quot;);
template &lt;typename T, typename... Ts&gt;
debug(std::initializer_list&lt;T&gt;&amp;&amp;, Ts&amp;&amp;...) -&gt; debug&lt;std::vector&lt;T&gt;, Ts...&gt;;

int main() {
    debug(bar::bar2, 5, 'A', 3.14f, &quot;foo&quot;);
    debug({bar::bar1, bar::bar2}, 5, 'A', 3.14f, &quot;foo&quot;);
    debug(5, 'A', 3.14f, &quot;foo&quot;);
    debug(&quot;bar&quot;, 123, 2.72);
}
</code></pre>
